            setDraft("");
            return;
          }
          if (parsed) {
            onChange?.(parsed);
            setDraft(formatDateTimeForTable(parsed));
            return;
          }
          setDraft(formatted);
        }}
        className={pickerEnabled ? withPickerPadding(className) : className}
      />
      {pickerEnabled ? (
        <NativeDatePickerBridge
          pickerType="datetime-local"
          value={value}
          onChange={applyStoredValue}
          title="Choose date and time"
        />
      ) : null}
    </div>
  );
